#!/usr/bin/env node
/**
 * Builds the static showcase.
 *
 * The reports are generated by the collector itself — the same renderer the CLI
 * uses — so the site shows real output rather than a mock-up. Tailwind compiles
 * the landing page; the reports keep their own inline styles and stay free of
 * scripts and external assets.
 */
import { spawnSync } from "node:child_process";
import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parseSnapshot, renderSnapshotHtml } from "../dist/index.js";

const repo = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const siteDir = join(repo, "site");
const publicDir = join(siteDir, "public");
const corpusDir = join(repo, "examples", "corpus");

const SEVERITIES = ["critical", "high", "medium", "low", "info"];
// Static class names: Tailwind cannot see classes built by interpolation.
const SEVERITY_CLASS = {
  critical: "text-critical",
  high: "text-high",
  medium: "text-medium",
  low: "text-low",
  info: "text-muted",
};

const LABELS = {
  "open-readonly": "Open · read-only",
  "open-destructive": "Open · destructive tools",
  "protected-ok": "Protected · discovery OK",
  "protected-no-prm": "Protected · no metadata",
  forbidden: "403 instead of 401",
  poisoned: "Poisoned metadata",
  "no-discovery": "No discovery methods",
  mixed: "Mixed posture",
  sparse: "Sparse metadata",
};

rmSync(publicDir, { recursive: true, force: true });
mkdirSync(join(publicDir, "reports"), { recursive: true });
mkdirSync(join(publicDir, "assets"), { recursive: true });

const files = readdirSync(corpusDir).filter((file) => file.endsWith(".json")).sort();
const cards = [];

for (const file of files) {
  const name = file.replace(/\.json$/, "");
  const snapshot = parseSnapshot(readFileSync(join(corpusDir, file), "utf8"));
  writeFileSync(join(publicDir, "reports", `${name}.html`), renderSnapshotHtml(snapshot));

  const counts = Object.fromEntries(
    SEVERITIES.map((severity) => [severity, snapshot.findings.filter((f) => f.severity === severity).length]),
  );
  const total = snapshot.findings.length;
  const chips = SEVERITIES.filter((severity) => counts[severity] > 0)
    .map(
      (severity) =>
        `<span class="border px-1.5 py-0.5 ${SEVERITY_CLASS[severity]}" style="border-color:currentColor">${severity} ${counts[severity]}</span>`,
    )
    .join("");
  const target = snapshot.probe.target.replace(/^https?:\/\//, "");

  cards.push({
    total,
    html: `<a href="reports/${name}.html" class="group block border border-line bg-panel p-4 transition hover:border-accent/60 hover:bg-panel-2">
          <div class="flex items-start justify-between gap-3">
            <span class="text-sm text-fg transition group-hover:text-accent">${LABELS[name] ?? name}</span>
            <span class="shrink-0 text-[10px] uppercase tracking-[0.16em] text-faint">${total} finding${total === 1 ? "" : "s"}</span>
          </div>
          <div class="mt-1 truncate text-[11px] text-faint">${target}</div>
          <div class="mt-3 flex flex-wrap gap-1.5 text-[10px] uppercase tracking-[0.14em]">${chips}</div>
        </a>`,
  });
}

cards.sort((a, b) => b.total - a.total);

const index = readFileSync(join(siteDir, "index.html"), "utf8").replace(
  "<!-- REPORTS -->",
  cards.map((card) => card.html).join("\n"),
);
writeFileSync(join(publicDir, "index.html"), index);

const SITE = "https://rubendelgadopareja.github.io/mcp-threat-observatory";
const urls = ["", "index.html", ...files.map((file) => `reports/${file.replace(/\.json$/, "")}.html`)];
writeFileSync(
  join(publicDir, "sitemap.xml"),
  `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls
    .map((path) => `  <url><loc>${SITE}/${path}</loc></url>`)
    .join("\n")}\n</urlset>\n`,
);
writeFileSync(join(publicDir, "robots.txt"), `User-agent: *\nAllow: /\nSitemap: ${SITE}/sitemap.xml\n`);

console.log(`reports: ${files.length} · landing: site/public/index.html`);

const tailwind = spawnSync(
  "npx",
  ["--yes", "@tailwindcss/cli", "-i", join(siteDir, "input.css"), "-o", join(publicDir, "assets", "app.css"), "--minify"],
  { stdio: "inherit", cwd: repo },
);
if (tailwind.status !== 0) {
  console.error("tailwind build failed");
  process.exit(tailwind.status ?? 1);
}
console.log("css: site/public/assets/app.css");
